/** The model's step ended without a tool call, so what it wrote is the turn's answer, pending its grounding check. The text itself is not in here. `held` says whether the answer waits for the verdict before anyone gets it. Voice starts to speak an answer that is not held at this point, and never earlier: text that turns out to come with a tool call is not an answer and must not be heard. */
export interface AnswerDrafted {
  seq: number;
  ts: number;
  turn_id: string | null;
  type: "answer.drafted";
  call_id: string;
  held: boolean;
}

/** A streamed answer did not pass its grounding check. Clients remove it. */
export interface AnswerRetracted {
  seq: number;
  ts: number;
  turn_id: string | null;
  type: "answer.retracted";
  reason: string;
}

/** The final text of the turn. Clients show it in place of whatever they streamed. It is sent only after the grounding check has passed, or for wording the app wrote itself. When `held` is true no deltas went out before it. */
export interface AssistantMessage {
  seq: number;
  ts: number;
  turn_id: string | null;
  type: "assistant.message";
  text: string;
  held: boolean;
  hits: RetrievalHit[];
}

